import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskG solver = new TaskG();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskG {
        static double[] cs = new double[1 << 21];
        static double[] sn = new double[1 << 21];
        static double[] csi = new double[1 << 21];
        static double[] sni = new double[1 << 21];

        static {
            for (int i = 0; i < cs.length; i++) {
                cs[i] = Math.cos(2 * Math.PI * i / cs.length);
                sn[i] = Math.sin(2 * Math.PI * i / cs.length);
                csi[i] = Math.cos(-2 * Math.PI * i / cs.length);
                sni[i] = Math.sin(-2 * Math.PI * i / cs.length);
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int mod = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (p > 0) {
                if ((p & 1) != 0) {
                    ans = multiplyMod(ans, v, mod);
                }
                p >>= 1;
                if (p == 0) break;
                v = multiplyMod(v, v, mod);
            }
            int res = 0;
            for (int x : ans) {
                res = (int) ((res + (long) x * x) % mod);
            }
            out.println(res);
        }

        static int[] multiplyMod(int[] a, int[] b, int mod) {
            int need = a.length + b.length - 1;
            int n = 2;
            while (n < need) n <<= 1;

            double[] aLowReal = new double[n];
            double[] aLowImag = new double[n];
            double[] aHighReal = new double[n];
            double[] aHighImag = new double[n];
            for (int i = 0; i < a.length; i++) {
                int x = (a[i] % mod + mod) % mod;
                aLowReal[i] = x & ((1 << 15) - 1);
                aHighReal[i] = x >> 15;
            }
            fft(aLowReal, aLowImag, false);
            fft(aHighReal, aHighImag, false);

            double[] bLowReal = new double[n];
            double[] bLowImag = new double[n];
            double[] bHighReal = new double[n];
            double[] bHighImag = new double[n];
            for (int i = 0; i < b.length; i++) {
                int x = (b[i] % mod + mod) % mod;
                bLowReal[i] = x & ((1 << 15) - 1);
                bHighReal[i] = x >> 15;
            }
            fft(bLowReal, bLowImag, false);
            fft(bHighReal, bHighImag, false);

            double[] lowLowReal = new double[n];
            double[] lowLowImag = new double[n];
            double[] midReal = new double[n];
            double[] midImag = new double[n];
            double[] highHighReal = new double[n];
            double[] highHighImag = new double[n];

            for (int i = 0; i < n; i++) {
                lowLowReal[i] = aLowReal[i] * bLowReal[i] - aLowImag[i] * bLowImag[i];
                lowLowImag[i] = aLowReal[i] * bLowImag[i] + aLowImag[i] * bLowReal[i];

                double lhReal = aLowReal[i] * bHighReal[i] - aLowImag[i] * bHighImag[i];
                double lhImag = aLowReal[i] * bHighImag[i] + aLowImag[i] * bHighReal[i];

                double hlReal = aHighReal[i] * bLowReal[i] - aHighImag[i] * bLowImag[i];
                double hlImag = aHighReal[i] * bLowImag[i] + aHighImag[i] * bLowReal[i];

                midReal[i] = lhReal + hlReal;
                midImag[i] = lhImag + hlImag;

                highHighReal[i] = aHighReal[i] * bHighReal[i] - aHighImag[i] * bHighImag[i];
                highHighImag[i] = aHighReal[i] * bHighImag[i] + aHighImag[i] * bHighReal[i];
            }

            fft(lowLowReal, lowLowImag, true);
            fft(midReal, midImag, true);
            fft(highHighReal, highHighImag, true);

            int[] res = new int[need];
            for (int i = 0; i < need; i++) {
                long low = (long) (lowLowReal[i] + 0.5);
                long mid = (long) (midReal[i] + 0.5);
                long high = (long) (highHighReal[i] + 0.5);
                res[i] = (int) ((low + ((mid % mod) << 15) + ((high % mod) << 30)) % mod);
            }
            return res;
        }

        static void fft(double[] a, double[] b, boolean inverse) {
            int n = a.length;
            int bits = 0;
            int temp = n;
            while (temp > 1) {
                temp >>= 1;
                bits++;
            }
            for (int i = 1; i < n; i++) {
                int j = reverseBits(i, bits);
                if (i < j) {
                    double tempA = a[i];
                    a[i] = a[j];
                    a[j] = tempA;
                    tempA = b[i];
                    b[i] = b[j];
                    b[j] = tempA;
                }
            }
            for (int len = 2; len <= n; len <<= 1) {
                int halfLen = len >> 1;
                for (int i = 0; i < n; i += len) {
                    int w = cs.length / len;
                    for (int j = 0, k = 0; j < halfLen; j++, k += w) {
                        double wA = inverse ? csi[k] : cs[k];
                        double wB = inverse ? sni[k] : sn[k];
                        double uA = a[i + j];
                        double uB = b[i + j];
                        double vA = a[i + j + halfLen] * wA - b[i + j + halfLen] * wB;
                        double vB = a[i + j + halfLen] * wB + b[i + j + halfLen] * wA;
                        a[i + j] = uA + vA;
                        b[i + j] = uB + vB;
                        a[i + j + halfLen] = uA - vA;
                        b[i + j + halfLen] = uB - vB;
                    }
                }
            }
            if (inverse) {
                for (int i = 0; i < n; i++) {
                    a[i] /= n;
                    b[i] /= n;
                }
            }
        }

        static int reverseBits(int x, int bits) {
            int res = 0;
            for (int i = 0; i < bits; i++) {
                res = (res << 1) | (x & 1);
                x >>= 1;
            }
            return res;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
